#[inline(never)]
unsafe fn WriteRingBuffer(
    mut s: *mut BrotliDecoderStateInternal,
    mut available_out: *mut size_t,
    mut next_out: *mut *mut uint8_t,
    mut total_out: *mut size_t,
    mut force: c_int,
) -> BrotliDecoderErrorCode {
    let available = unsafe { &mut *available_out }; // SAFETY: caller provides a valid non-null mutable pointer per function contract.
    let state = unsafe { &mut *s }; // SAFETY: caller provides a valid non-null mutable decoder state pointer per function contract.

    if state.meta_block_remaining_len < 0 as c_int {
        return BROTLI_DECODER_ERROR_FORMAT_BLOCK_LENGTH_1 as c_int as BrotliDecoderErrorCode;
    }

    let start = unsafe {
        state
            .ringbuffer
            .offset((state.partial_pos_out & state.ringbuffer_mask as size_t) as isize)
    }; // SAFETY: offset is computed exactly as in the original code and relies on ringbuffer allocation/layout invariants maintained by the decoder.

    let to_write: size_t = UnwrittenBytes(s, BROTLI_TRUE);
    let num_written: size_t = if *available > to_write { to_write } else { *available };

    if !next_out.is_null() {
        let out = unsafe { *next_out }; // SAFETY: next_out is checked non-null above; reading the pointed-to output pointer matches original behavior.
        if out.is_null() {
            unsafe {
                *next_out = start;
            } // SAFETY: next_out is non-null and writable per function contract.
        } else {
            unsafe {
                memcpy(out as *mut c_void, start as *const c_void, num_written);
                *next_out = out.offset(num_written as isize);
            } // SAFETY: preserves original memcpy/offset behavior and relies on caller-provided output buffer capacity and valid ringbuffer source.
        }
    }

    *available = (*available as c_ulong).wrapping_sub(num_written as c_ulong) as size_t;
    state.partial_pos_out =
        (state.partial_pos_out as c_ulong).wrapping_add(num_written as c_ulong) as size_t;

    if !total_out.is_null() {
        unsafe {
            *total_out = state.partial_pos_out;
        } // SAFETY: total_out is checked non-null above and is writable per function contract.
    }

    if num_written < to_write {
        return if state.ringbuffer_size == (1 as c_int) << state.window_bits() as c_int || force != 0
        {
            BROTLI_DECODER_NEEDS_MORE_OUTPUT
        } else {
            BROTLI_DECODER_SUCCESS
        };
    }

    let ringbuffer_size = state.ringbuffer_size;
    if ringbuffer_size == (1 as c_int) << state.window_bits() as c_int && state.pos >= ringbuffer_size
    {
        state.pos -= ringbuffer_size;
        state.rb_roundtrips = state.rb_roundtrips.wrapping_add(1);
        state.set_should_wrap_ringbuffer((if state.pos as size_t != 0 as size_t {
            1 as c_int
        } else {
            0 as c_int
        }) as c_uint);
    }

    BROTLI_DECODER_SUCCESS
}

